 if(d.focusRival){const f=state.ai?.factions.find(f=>f.id===d.focusRival),c=f?.villages[0];if(c){ui.page='map';ui.mapX=c.x;ui.mapY=c.y;ui.tileX=c.x;ui.tileY=c.y;render();}return;}
